import { Link2Icon } from "@radix-ui/react-icons";
import healthy from "../../../images/footer/levels/Healthy.svg";
import annotated from "../../../images/footer/levels/Annotated.svg";
import minor from "../../../images/footer/levels/Minor.svg";
import medium from "../../../images/footer/levels/Medium.svg";
import major from "../../../images/footer/levels/Major.svg";
import critical from "../../../images/footer/levels/Critical.svg";

import type { CarouselItemData } from "./types";

interface CarouselItemProps {
  item: CarouselItemData;
}

const CarouselItem = ({ item }: CarouselItemProps) => {
  let imgurl: string;
  if (item.incident.health >= 100) {
    imgurl = healthy;
  } else if (item.incident.health >= 75) {
    imgurl = annotated;
  } else if (item.incident.health >= 50) {
    imgurl = minor;
  } else if (item.incident.health >= 25) {
    imgurl = medium;
  } else if (item.incident.health >= 0) {
    imgurl = major;
  } else {
    imgurl = critical;
  }

  return (
    <li className="carousel__item">
      <article className="carousel__entry">
        <div className="carousel__identity">
          <img
            className="carousel__icon"
            src={imgurl}
            width={32}
            height={32}
            alt={`${item.system} health ${item.incident.health}%`}
          />
          <span className="carousel__system">{item.system}</span>
        </div>
        <div className="carousel__meta">
          <span className="carousel__usercount">{item.usercount}</span>
          <a
            className="carousel__link"
            href={item.href}
            aria-label={`Open ${item.system}`}
            title={`Open ${item.system}`}
          >
            <Link2Icon />
          </a>
        </div>
      </article>
    </li>
  );
};

export default CarouselItem;
