import { useEffect, useRef, useState } from "react";
import { CaretLeftIcon, CaretRightIcon } from "@radix-ui/react-icons";
import "./Carousel.css";
import { useCarouselItems } from "@/stores/SSEStore";
import CarouselItem from "./CarouselItem";

export default function Carousel() {
  const items = useCarouselItems();
  const carouselRef = useRef<HTMLUListElement | null>(null);
  const [canScrollPrev, setCanScrollPrev] = useState(false);
  const [canScrollNext, setCanScrollNext] = useState(false);

  const updateScrollState = () => {
    const carousel = carouselRef.current;

    if (!carousel) {
      return;
    }

    const maxScrollLeft = carousel.scrollWidth - carousel.clientWidth;

    setCanScrollPrev(carousel.scrollLeft > 0);
    setCanScrollNext(carousel.scrollLeft < maxScrollLeft - 1);
  };

  const scrollCarousel = (direction: "prev" | "next") => {
    const carousel = carouselRef.current;

    if (!carousel) {
      return;
    }

    const firstItem = carousel.querySelector<HTMLElement>(".carousel__item");
    const styles = window.getComputedStyle(carousel);
    const gap = Number.parseFloat(styles.columnGap || styles.gap || "16");
    const distance = firstItem
      ? firstItem.getBoundingClientRect().width + gap
      : carousel.clientWidth * 0.8;

    carousel.scrollBy({
      left: direction === "next" ? distance : -distance,
      behavior: "smooth",
    });
  };

  useEffect(() => {
    const carousel = carouselRef.current;

    if (!carousel) {
      return;
    }

    const handleScroll = () => updateScrollState();

    updateScrollState();
    carousel.addEventListener("scroll", handleScroll, { passive: true });
    window.addEventListener("resize", updateScrollState);

    return () => {
      carousel.removeEventListener("scroll", handleScroll);
      window.removeEventListener("resize", updateScrollState);
    };
  }, [items.length]);

  return (
    <div className="carousel-shell">
      <button
        className="carousel__arrow carousel__arrow--prev"
        type="button"
        aria-label="Scroll carousel left"
        aria-controls="footer-carousel"
        disabled={!canScrollPrev}
        onClick={() => scrollCarousel("prev")}
      >
        <CaretLeftIcon />
      </button>
      <ul ref={carouselRef} id="footer-carousel" className="carousel">
        {items.map((item) => (
          <CarouselItem key={item.system} item={item} />
        ))}
      </ul>
      <button
        className="carousel__arrow carousel__arrow--next"
        type="button"
        aria-label="Scroll carousel right"
        aria-controls="footer-carousel"
        disabled={!canScrollNext}
        onClick={() => scrollCarousel("next")}
      >
        <CaretRightIcon />
      </button>
    </div>
  );
}
